import{_ as t,o as n,c as i,a4 as r}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0018 — Référentiel d'accessibilité en configuration versionnée, jamais en base ni en code","description":"Extrait de docs/adr/0018-referentiel-accessibilite-externalise.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0018 — Référentiel d'accessibilité en configuration versionnée, jamais en base ni en code","description":"Extrait de docs/adr/0018-referentiel-accessibilite-externalise.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0018-referentiel-accessibilite-externalise.md","filePath":"developpeurs/adr/0018-referentiel-accessibilite-externalise.md"}`),a={name:"developpeurs/adr/0018-referentiel-accessibilite-externalise.md"};function s(o,e,l,u,c,d){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0018--référentiel-daccessibilité-en-configuration-versionnée-jamais-en-base-ni-en-code" tabindex="-1">ADR-0018 — Référentiel d&#39;accessibilité en configuration versionnée, jamais en base ni en code <a class="header-anchor" href="#adr-0018--référentiel-daccessibilité-en-configuration-versionnée-jamais-en-base-ni-en-code" aria-label="Permalink to &quot;ADR-0018 — Référentiel d&#39;accessibilité en configuration versionnée, jamais en base ni en code {#adr-0018--référentiel-daccessibilité-en-configuration-versionnée-jamais-en-base-ni-en-code}&quot;">​</a></h1><p><strong>Date :</strong> 20 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §12.2 (déclaration d&#39;accessibilité générée à partir des résultats d&#39;audit stockés en base), §17 point ouvert #8 (RGAA 5 annoncé fin 2026) ; <code>docs/plan-action-agile.md</code> §3.1.bis</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le CDC demande que le CMS produise une <strong>déclaration d&#39;accessibilité</strong> à partir de « résultats d&#39;audit stockés en base » (§12.2). Le point ouvert #8 y ajoute une contrainte qui n&#39;est pas une question mais une décision déjà prise par le CDC lui-même : <em>« Version 5 annoncée fin 2026, ne pas figer le moteur d&#39;audit sur la grille 4.1.2 »</em>, avec pour réponse <em>« référentiel de critères externalisé dans une configuration versionnée dès la conception du moteur d&#39;audit — pas de décision à date fixe, contrainte de conception à respecter dès le début »</em>.</p><p>Le plan d&#39;action range explicitement ce point parmi ceux « restés hors ADR » côté §17. Cette ADR n&#39;arbitre donc pas <em>s&#39;il faut</em> externaliser : elle acte <strong>où</strong> et <strong>sous quelle forme</strong>, parce que le choix technique reste ouvert et que trois options avaient toutes l&#39;air raisonnables.</p><p><strong>Ce qui est en jeu concrètement.</strong> Un référentiel RGAA, c&#39;est 13 thématiques, 106 critères, trois niveaux, une numérotation, des libellés. Le RGAA 5 changera tout cela — probablement le nombre de critères, sûrement la numérotation, peut-être les niveaux eux-mêmes. Or des audits saisis sous RGAA 4.1.2 devront rester lisibles après la bascule : une déclaration publiée en 2026 doit continuer d&#39;afficher son taux en 2028, calculé sur la grille sous laquelle elle a été établie. Une collectivité peut par ailleurs auditer sous une déclinaison locale, et le CMS n&#39;a aucune raison d&#39;être français-seulement.</p><h3 id="les-trois-options" tabindex="-1">Les trois options <a class="header-anchor" href="#les-trois-options" aria-label="Permalink to &quot;Les trois options {#les-trois-options}&quot;">​</a></h3><p><strong>A. Une table <code>accessibility_criteria</code> alimentée par migration.</strong> C&#39;est la lecture littérale de « stockés en base ». Elle permet une clé étrangère depuis les résultats, donc une intégrité référentielle réelle. Elle a trois défauts qui se cumulent : publier le RGAA 5 devient une <strong>migration de données à jouer sur chaque installation</strong> ; corriger une coquille de libellé exige un déploiement ; et la question « que devient un résultat rattaché à un critère supprimé ? » n&#39;a aucune bonne réponse — <code>CASCADE</code> efface des verdicts saisis par un auditeur, <code>RESTRICT</code> empêche la mise à jour du référentiel.</p><p><strong>B. Des constantes Python (dataclasses, <code>Literal</code>, dictionnaire de module).</strong> La plus simple à écrire, et celle que la contrainte du point #8 vise explicitement. Elle fige la grille dans le code livré : une collectivité qui audite autrement doit forker, et un <code>Literal[&quot;A&quot;, &quot;AA&quot;, &quot;AAA&quot;]</code> posé quelque part contamine ensuite tout le typage — au moment du RGAA 5, il faudrait retrouver chaque endroit où la forme du RGAA 4 a été présumée.</p><p><strong>C. Des fichiers YAML versionnés, chargés au démarrage.</strong> C&#39;est le patron déjà retenu par ce dépôt pour le Model Registry de l&#39;Epic E8 (ADR-0011) : un répertoire livré avec la distribution, un répertoire supplémentaire pour l&#39;exploitant, une validation Pydantic stricte au chargement, un refus global plutôt qu&#39;un chargement partiel.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Le référentiel d&#39;accessibilité est un fichier YAML versionné, chargé au démarrage — option C, avec le patron d&#39;ADR-0011 repris tel quel plutôt qu&#39;un troisième format inventé.</strong></p><ul><li>Les référentiels livrés vivent dans <code>app/compliance/referentials/</code> ; <code>ACCESSIBILITY_REFERENTIAL_DIR</code> ajoute un répertoire d&#39;exploitant, sans jamais écraser les fichiers livrés ni être écrasé par une mise à jour du CMS.</li><li>Le chargement est installé par le composeur d&#39;application (<code>app/main.py</code>), via <code>install_referential_catalogue()</code> — même patron <code>install_*</code> / <code>reset_*</code> qu&#39;en E7 et E8.</li><li>Les clés sont <strong>uniques toutes sources confondues</strong> : un fichier d&#39;intégrateur ne redéfinit pas <code>rgaa-4.1.2</code>. Sans cela, le taux d&#39;un audit passé pourrait changer au redémarrage du serveur selon l&#39;ordre de lecture des fichiers.</li></ul><p><strong>Trois conséquences de typage, qui sont le cœur de la décision :</strong></p><ol><li><strong>Aucun niveau n&#39;est une union fermée.</strong> <code>Criterion.level</code> est une <code>str | None</code>, pas un <code>Literal[&quot;A&quot;, &quot;AA&quot;, &quot;AAA&quot;]</code>. Un référentiel dont les niveaux s&#39;appellent « essentiel » et « souhaitable » se charge sans modification de code.</li><li><strong>Aucun numéro de critère n&#39;est présumé.</strong> <code>CriterionNumber</code> accepte <code>1.1</code> comme <code>E-01</code> ; rien dans le code n&#39;analyse un numéro pour en déduire une thématique.</li><li><strong>La méthode de calcul du taux est déclarée par le fichier.</strong> <code>conformance_rate_levels</code> dit quels niveaux entrent dans le taux de conformité. Coder « A et AA » en Python aurait été une décision méthodologique prise par le CMS à la place de l&#39;autorité qui publie le référentiel — et fausse dès qu&#39;un référentiel calcule autrement.</li></ol><p><strong>En base, on stocke les résultats et rien d&#39;autre.</strong> <code>accessibility_audit_results.criterion_number</code> est une chaîne, <strong>sans clé étrangère et sans contrainte <code>CHECK</code> énumérant les critères</strong>. Une contrainte <code>CHECK</code> aurait été l&#39;option A déguisée, et la pire de ses formes : la saisie d&#39;un audit RGAA 5 aurait échoué sur une erreur de base de données au lieu d&#39;un message métier. La validation d&#39;un numéro se fait à l&#39;écriture, <strong>contre le référentiel de l&#39;audit concerné</strong>, là où le message d&#39;erreur peut nommer la grille attendue.</p><p><strong>L&#39;audit porte sa grille.</strong> <code>accessibility_audits.referential_key</code> est obligatoire et sans valeur par défaut — ni en base, ni en configuration, ni dans le contrat d&#39;API. Un audit énonce toujours sous quelle grille il a été conduit ; un « référentiel par défaut de l&#39;installation » serait redevenu, à l&#39;usage, « le référentiel du CMS ». <code>referential_label</code> en fige l&#39;instantané textuel, pour qu&#39;un audit reste lisible même quand le fichier n&#39;est plus déployé.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><ul><li><strong>Option A (table de critères)</strong> — écartée : transforme une échéance réglementaire externe en migration de données sur le parc installé, et pose une question sans bonne réponse sur le devenir des verdicts saisis.</li><li><strong>Option B (constantes Python)</strong> — écartée : c&#39;est nommément ce que le point ouvert #8 interdit.</li><li><strong>JSON plutôt que YAML</strong> — écarté : le format n&#39;admet pas de commentaires, et un référentiel a besoin d&#39;expliquer d&#39;où il vient et ce qu&#39;il n&#39;est pas (une transcription, pas une source de droit). Le dépôt a par ailleurs déjà tranché pour le YAML en ADR-0011 ; un second format de configuration versionnée n&#39;aurait rien apporté.</li><li><strong>Un plugin par référentiel (Plugin SDK, E7)</strong> — écarté : un référentiel est une donnée, pas du comportement. Le raisonnement d&#39;ADR-0011 s&#39;applique mot pour mot — les registres décrivant du comportement restent en Python, ceux décrivant des faits extérieurs qui changent sans que le CMS change vont en YAML.</li></ul><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives.</strong></p><ul><li>Le RGAA 5 se prend en charge en déposant un fichier : aucun déploiement de code, aucune migration, aucune reprise de données.</li><li>Les audits antérieurs restent calculables sous leur grille d&#39;origine, indéfiniment.</li><li>Le formulaire de saisie côté admin est construit depuis <code>GET /compliance/accessibility/referentials/{clé}</code> : le front ne connaît aucun critère non plus, la contrainte tient de bout en bout.</li><li>Une collectivité ou un intégrateur peut auditer sous sa propre grille sans forker le CMS.</li></ul><p><strong>Négatives, assumées.</strong></p><ul><li><strong>Pas d&#39;intégrité référentielle en base.</strong> Un référentiel retiré de l&#39;installation laisse des résultats orphelins. Traité et non ignoré : <code>ConformanceScore.orphan_results</code> les nomme, ils sont exclus du taux, et un avertissement l&#39;explique dans la déclaration — un taux qui change tout seul après une mise à jour de fichier, sans que rien ne le dise, était le vrai risque.</li><li><strong>Le référentiel livré est une transcription.</strong> Une formulation de critère peut avoir dérivé du texte de la DINUM. La correction se fait en éditant le fichier, et le fichier le dit en tête ; c&#39;est précisément parce qu&#39;il est une donnée que la correction ne passe pas par un cycle de développement.</li><li><strong>Deux référentiels installés obligent l&#39;admin à demander lequel</strong> à l&#39;ouverture d&#39;un audit. C&#39;est un pas d&#39;interface supplémentaire, et c&#39;est correct : un audit qui ne dit pas sous quelle grille il a été conduit n&#39;est pas un audit.</li></ul><h2 id="portée--ce-que-cette-adr-ne-décide-pas" tabindex="-1">Portée : ce que cette ADR ne décide pas <a class="header-anchor" href="#portée--ce-que-cette-adr-ne-décide-pas" aria-label="Permalink to &quot;Portée : ce que cette ADR ne décide pas {#portée--ce-que-cette-adr-ne-décide-pas}&quot;">​</a></h2><p>Elle ne dit rien de la <strong>conformité</strong> du site ni de la valeur juridique de la déclaration produite. Le document généré est un <strong>constat technique sur la base des résultats saisis</strong>, jamais une attestation d&#39;accessibilité, et il le porte en tête, non effaçable (<code>app/compliance/disclaimer.py</code>). La validation juridique n&#39;a pas été obtenue à ce stade du projet (<code>docs/plan-action-agile.md</code> §3.1.bis, points #7 et #8) ; jusque-là, aucune affirmation de conformité réglementaire ne doit apparaître dans l&#39;UI produit.</p><p>Elle ne décide pas non plus d&#39;un <strong>audit automatisé</strong> : il n&#39;y en a pas, et le CDC n&#39;en demande pas. Un audit RGAA se conduit par échantillonnage de pages et jugement humain, hors de la plateforme ; le CMS conserve et restitue les résultats saisis.</p>',27)])])}const g=t(a,[["render",s]]);export{m as __pageData,g as default};
